function executesScript(event) {
  var claimId = event.getParameter('claimId');
  var claimAmount = event.getParameter('claimAmount');
  var policyActive = event.getParameter('policyActive');

  var isPolicyActive = (policyActive === true || policyActive === 'true');
  var amount = Number(claimAmount);

  if (!isPolicyActive) {
    event.setParameter('decision', 'DENY');
    event.setParameter('reason', 'Policy is inactive');
  } else if (amount <= 1000) {
    event.setParameter('decision', 'APPROVE');
    event.setParameter('reason', 'Claim amount is within auto-approval threshold');
  } else {
    event.setParameter('decision', 'REVIEW');
    event.setParameter('reason', 'Claim amount exceeds threshold; manual review required');
  }
}

function executeScript(event) {
  executesScript(event);
}
